float map(vec3 p, float time) {
  vec3 id = floor(p);
  vec3 q = fract(p) - 0.5;
  float a = time * 0.6 + id.x * 1.1 + id.z * 0.7;
  float c = cos(a);
  float s = sin(a);
  q.xz = mat2(c, s, -s, c) * q.xz;
  return sdBox(q, vec3(0.22));
}

float march(vec3 ro, vec3 rd, float time) {
  float t = 0.0;
  for (int i = 0; i < 64; i++) {
    vec3 p = ro + rd * t;
    float d = map(p, time);
    if (d < 0.001) break;
    t += d;
    if (t > 20.0) break;
  }
  return t;
}
